def get_davis_palette_list() -> list[list[int]]:
    """
    Convert the DAVIS palette bytes to a list of [R, G, B] triplets.

    Returns:
        List of 256 [R, G, B] color triplets
    """
    return [[DAVIS_PALETTE_BYTES[i * 3], DAVIS_PALETTE_BYTES[i * 3 + 1], DAVIS_PALETTE_BYTES[i * 3 + 2]] for i in range(len(DAVIS_PALETTE_BYTES) // 3)]


# Pre-computed list format for convenience
DAVIS_PALETTE = get_davis_palette_list()
